import blocksIndex from '../../circuits/blocks-index.json' with { type: 'json' };
import type { Part, Schematic, Wire } from './schematic-types';

export interface Expectation { signal: string; statistic: string; value: number; tolerance: number; meaning: string }
export interface CircuitBlock {
  id: string; name: string; category: 'indicators' | 'switching' | 'interfacing' | 'signal' | 'power';
  description: string; notes: string; expectations: Expectation[]; circuit: Schematic;
}

// Generated by `python -m backend.parts_cli index`; CI checks it matches the validated block files.
export const BLOCKS = blocksIndex as unknown as CircuitBlock[];
export const CATEGORY_NAMES: Record<CircuitBlock['category'], string> = {
  indicators: 'Indicators', switching: 'Switching', interfacing: 'Interfacing', signal: 'Signal', power: 'Power',
};
const GRID = { minX: 2, maxX: 38, minY: 2, maxY: 22 };

/** Keep the id if it's free; otherwise its letter prefix plus the first free number (same rule as the server). */
export function freeIdentifier(identifier: string, taken: Set<string>): string {
  if (!taken.has(identifier)) return identifier;
  const prefix = identifier.replace(/\d+$/, '').slice(0, 12) || 'X';
  let number = 1;
  while (taken.has(prefix + number)) number++;
  return prefix + number;
}

function bounds(parts: Part[]) {
  const xs = parts.map(part => part.x), ys = parts.map(part => part.y);
  return { left: Math.min(...xs), top: Math.min(...ys), width: Math.max(...xs) - Math.min(...xs), height: Math.max(...ys) - Math.min(...ys) };
}

/** Add a block's parts and wires with its top-left part at (column, row), renaming clashing ids. */
export function mergeBlock(schematic: Schematic, block: CircuitBlock, column: number, row: number): Schematic {
  if (schematic.parts.length + block.circuit.parts.length > 20 || schematic.wires.length + block.circuit.wires.length > 40) {
    throw new Error('Inserting ' + block.name + ' would exceed 20 parts or 40 wires.');
  }
  const { left, top } = bounds(block.circuit.parts);
  const taken = new Set(schematic.parts.map(part => part.id));
  const renamed = new Map<string, string>();
  const placed = block.circuit.parts.map(part => {
    const id = freeIdentifier(part.id, taken);
    taken.add(id); renamed.set(part.id, id);
    const x = part.x - left + column, y = part.y - top + row;
    if (x < GRID.minX || x > GRID.maxX || y < GRID.minY || y > GRID.maxY) throw new Error(block.name + " doesn't fit there; clear some space on the grid.");
    return { ...part, id, x, y };
  });
  const linked: Wire[] = block.circuit.wires.map(wire => ({ a: { ...wire.a, part: renamed.get(wire.a.part)! }, b: { ...wire.b, part: renamed.get(wire.b.part)! } }));
  return { ...schematic, parts: [...schematic.parts, ...placed], wires: [...schematic.wires, ...linked] };
}

/** Where to insert a block: the first spot clear of every existing part by two grid cells, otherwise the spot
 * that collides with the fewest parts (`overlaps` says how many, so the user can be told to tidy up). */
export function freeSpot(schematic: Schematic, block: CircuitBlock): { column: number; row: number; overlaps: number } | null {
  const { width, height } = bounds(block.circuit.parts);
  let best: { column: number; row: number; overlaps: number } | null = null;
  for (let row = GRID.minY; row + height <= GRID.maxY; row++) {
    for (let column = GRID.minX; column + width <= GRID.maxX; column++) {
      const overlaps = schematic.parts.filter(part => part.x >= column - 2 && part.x <= column + width + 2
        && part.y >= row - 2 && part.y <= row + height + 2).length;
      if (overlaps === 0) return { column, row, overlaps };
      if (!best || overlaps < best.overlaps) best = { column, row, overlaps };
    }
  }
  return best;
}
